package com.pulsesg.support.exception;
import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.ConstraintViolationException; import java.time.Instant; import java.util.*; import org.slf4j.*; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.http.*; import org.springframework.security.authentication.BadCredentialsException; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class GlobalExceptionHandler { private static final Logger log=LoggerFactory.getLogger(GlobalExceptionHandler.class); @ExceptionHandler(AppExceptions.NotFound.class) ResponseEntity<?> notFound(RuntimeException e,HttpServletRequest r){return body(404,e.getMessage(),r);} @ExceptionHandler(AppExceptions.Conflict.class) ResponseEntity<?> conflict(RuntimeException e,HttpServletRequest r){return body(409,e.getMessage(),r);} @ExceptionHandler(DataIntegrityViolationException.class) ResponseEntity<?> duplicate(DataIntegrityViolationException e,HttpServletRequest r){return body(409,"Email is already registered",r);} @ExceptionHandler(BadCredentialsException.class) ResponseEntity<?> credentials(Exception e,HttpServletRequest r){return body(401,"Invalid email or password",r);} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<?> validation(MethodArgumentNotValidException e,HttpServletRequest r){return body(400,"Please check the submitted fields",r);} @ExceptionHandler(Exception.class) ResponseEntity<?> generic(Exception e,HttpServletRequest r){log.error("Unhandled exception on {} {}",r.getMethod(),r.getRequestURI(),e);return body(500,"An unexpected error occurred",r);} private ResponseEntity<?> body(int status,String message,HttpServletRequest r){return ResponseEntity.status(status).body(Map.of("timestamp",Instant.now(),"status",status,"message",message,"path",r.getRequestURI()));}}
